import json
import math


def _normalize(report, restore_tuples):
    if not isinstance(report, dict) or set(report) != {"title", "points", "meta"}:
        raise TypeError("report has an invalid structure")
    if not isinstance(report["title"], str):
        raise TypeError("title must be a string")
    if not isinstance(report["points"], list):
        raise TypeError("points must be a list")
    if not isinstance(report["meta"], dict):
        raise TypeError("meta must be a dictionary")

    points = []
    for point in report["points"]:
        expected = list if restore_tuples else tuple
        if not isinstance(point, expected) or len(point) != 2:
            raise TypeError("each point must contain two coordinates")
        normalized = []
        for coordinate in point:
            if isinstance(coordinate, bool) or not isinstance(coordinate, (int, float)):
                raise TypeError("coordinates must be numeric")
            if not math.isfinite(coordinate):
                raise ValueError("coordinates must be finite")
            normalized.append(coordinate)
        points.append(tuple(normalized) if restore_tuples else normalized)

    try:
        meta = json.loads(json.dumps(report["meta"], allow_nan=False))
    except (TypeError, ValueError) as exc:
        raise TypeError("meta must be JSON-compatible") from exc
    return {"title": report["title"], "points": points, "meta": meta}


def freeze_report(report):
    normalized = _normalize(report, False)
    return json.dumps(
        normalized,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def thaw_report(blob):
    if not isinstance(blob, bytes):
        raise TypeError("blob must be bytes")
    try:
        decoded = json.loads(blob.decode("utf-8"))
        return _normalize(decoded, False)
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError("blob does not contain a valid report") from exc
